<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {Plus,RefreshCw,Save,Shuffle,Trash2,X} from 'lucide-vue-next'
import {api,key} from '../api/account'
import {themes,icons,actions,type Promotion,type PromotionInput} from '../api/promotions'
import PromotionCard from './PromotionCard.vue'
const emit=defineEmits<{notify:[message:string]}>()
const items=ref<Promotion[]>([]),loading=ref(false),busy=ref(false),error=ref(''),draft=ref<(PromotionInput&{id:string})|null>(null),deleting=ref('')
const published=computed(()=>items.value.filter(p=>p.enabled).length)
async function load(){loading.value=true;error.value='';try{items.value=await api<Promotion[]>('/admin/promotions')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function newActivity(){const counts=Object.fromEntries(themes.map(t=>[t.id,items.value.filter(p=>p.theme===t.id).length]));const theme=[...themes].sort((a,b)=>counts[a.id]!-counts[b.id]!)[0]!.id;draft.value={id:key(),version:0,title:'',tagline:'专属福利',summary:'',content:'',button:'查看详情',action:'details',icon:icons[items.value.length%icons.length]!.id,theme,enabled:false,sort:Math.min(9999,Math.max(0,...items.value.map(p=>p.sort))+10)};error.value='';deleting.value=''}
function edit(p:Promotion){const {updated_at,...data}=p;draft.value={...data};error.value='';deleting.value=''}
function recolor(){if(!draft.value)return;const i=themes.findIndex(t=>t.id===draft.value!.theme);draft.value.theme=themes[(i+1)%themes.length]!.id}
async function save(){if(!draft.value||busy.value)return;busy.value=true;error.value='';const {id,...payload}=draft.value;try{await api<Promotion>(`/admin/promotions/${encodeURIComponent(id)}`,'PUT',payload);draft.value=null;await load();emit('notify','活动已保存')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function toggle(p:Promotion){if(busy.value)return;busy.value=true;error.value='';try{const {id,updated_at,...payload}=p;await api(`/admin/promotions/${encodeURIComponent(id)}`,'PUT',{...payload,enabled:!p.enabled});await load();emit('notify',p.enabled?'活动已下架':'活动已上架')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(p:Promotion){if(busy.value)return;busy.value=true;error.value='';try{await api(`/admin/promotions/${encodeURIComponent(p.id)}`,'DELETE',{version:p.version});deleting.value='';await load();emit('notify','活动已删除')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>void load())
</script>
<template><div class="admin-promotions"><div v-if="error" class="form-error" role="alert">{{error}}</div><div class="activity-toolbar"><p>共 {{items.length}} 个活动 · {{published}} 个已上架</p><div><button class="secondary-button" :disabled="loading||busy||!!draft" @click="load"><RefreshCw :size="15"/>刷新列表</button><button class="primary-button" :disabled="loading||busy||!!draft" @click="newActivity"><Plus :size="16"/>新增活动</button></div></div>
<section v-if="draft" class="surface activity-editor"><div class="surface-heading"><h3>{{draft.version?'编辑活动':'新增活动'}}</h3><button class="icon-button" :disabled="busy" aria-label="关闭活动编辑" @click="draft=null"><X/></button></div><div class="activity-editor-grid"><form class="form-stack" @submit.prevent="save"><fieldset :disabled="busy"><label>活动标题<input v-model="draft.title" maxlength="40" required placeholder="例如：新会员专属礼遇"/></label><label>封面小标题<input v-model="draft.tagline" maxlength="30" placeholder="例如：限时福利"/></label><label>活动简介<textarea v-model="draft.summary" maxlength="200" rows="3" required placeholder="封面展示的简短介绍，支持换行"/></label><label>活动详情<textarea v-model="draft.content" maxlength="10000" rows="6" placeholder="填写参与方式、活动规则等，支持换行"/></label><div class="activity-fields"><label>按钮文字<input v-model="draft.button" maxlength="20" required/></label><label>按钮去向<select v-model="draft.action"><option v-for="a in actions" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>封面图标<select v-model="draft.icon"><option v-for="i in icons" :key="i.id" :value="i.id">{{i.name}}</option></select></label><label>展示排序<input v-model.number="draft.sort" type="number" min="0" max="9999" step="1" required/></label></div><p class="form-hint">排序值越小越靠前；按钮去向为“查看活动详情”时，点击打开详情弹窗。</p><div class="cover-controls"><span>封面配色</span><button type="button" class="text-button" @click="recolor"><Shuffle :size="14"/>自动换色</button></div><div class="cover-swatches"><button v-for="t in themes" :key="t.id" type="button" :style="{background:t.bg,color:t.ink}" :aria-label="`封面配色${t.name}`" :aria-pressed="draft.theme===t.id" :class="{selected:draft.theme===t.id}" @click="draft.theme=t.id">{{t.name}}</button></div><label class="checkbox-label"><input v-model="draft.enabled" type="checkbox"/>上架到福利活动</label><div class="activity-save"><button type="button" class="secondary-button" @click="draft=null">取消</button><button type="submit" class="primary-button"><Save :size="16"/>{{busy?'保存中…':'保存活动'}}</button></div></fieldset></form><aside class="activity-preview"><span>封面预览</span><PromotionCard :promotion="draft" preview/></aside></div></section>
<p v-if="loading" class="loading-line" role="status">正在加载活动…</p><div v-else-if="!items.length&&!draft" class="empty-state"><h3>还没有活动</h3><p>新增活动，自动生成专属配色封面。</p></div><div v-else class="activity-admin-grid"><section v-for="p in items" :key="p.id" class="activity-admin-item"><PromotionCard :promotion="p" preview/><div class="activity-item-meta"><span class="badge" :class="p.enabled?'active':'disabled'">{{p.enabled?'已上架':'未上架'}}</span><span>排序 {{p.sort}}</span></div><div v-if="deleting===p.id" class="activity-delete"><p>确认删除“{{p.title}}”？</p><button class="secondary-button" :disabled="busy" @click="deleting=''">取消</button><button class="danger-button" :disabled="busy" @click="remove(p)">确认删除</button></div><div v-else class="activity-item-actions"><button class="secondary-button" :disabled="busy||!!draft" @click="edit(p)">编辑</button><button class="secondary-button" :disabled="busy||!!draft" @click="toggle(p)">{{p.enabled?'下架':'上架'}}</button><button class="icon-button" :disabled="busy||!!draft" :aria-label="`删除活动${p.title}`" @click="deleting=p.id"><Trash2 :size="17"/></button></div></section></div></div></template>
<style scoped>
.activity-toolbar,.activity-toolbar>div{display:flex;align-items:center;justify-content:space-between;gap:12px}.activity-toolbar{margin-bottom:20px}.activity-toolbar p{font-size:12px;color:#9e90ae}.activity-editor{margin-bottom:24px}.activity-editor-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px}.activity-editor fieldset{border:0;padding:0;margin:0;min-width:0;display:flex;flex-direction:column;gap:16px}.activity-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.activity-preview{position:sticky;top:16px;align-self:start;min-width:0}.activity-preview>span{display:block;font-size:12px;color:#9f90af;margin-bottom:12px}.activity-save,.cover-controls{display:flex;justify-content:space-between;align-items:center;gap:10px}.cover-controls{font-size:12px;color:#9784aa}.cover-controls button{display:flex;align-items:center;gap:6px}.cover-swatches{display:flex;gap:8px;flex-wrap:wrap}.cover-swatches button{font-size:11px;padding:9px;border:2px solid transparent;border-radius:8px}.cover-swatches button.selected{border-color:currentColor}.activity-admin-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.activity-admin-item{background:#fff;border:1px solid #ece7f2;border-radius:18px;overflow:hidden;display:flex;flex-direction:column}.activity-admin-item .promotion-cover{border:0;border-radius:0;flex:1}.activity-item-meta{display:flex;align-items:center;gap:14px;padding:14px 20px 0;font-size:11px;color:#a293b1}.activity-item-actions{display:flex;gap:9px;align-items:center;padding:14px 20px}.activity-item-actions .icon-button{margin-left:auto}.activity-delete{padding:16px 20px;font-size:12px;color:#b85768}.activity-delete p{margin-bottom:12px}.activity-delete button{margin-right:10px}.activity-toolbar .primary-button,.activity-toolbar .secondary-button{white-space:nowrap}
@media(max-width:1000px){.activity-editor-grid{grid-template-columns:1fr}.activity-preview{position:static}.activity-admin-grid{grid-template-columns:1fr}}@media(max-width:640px){.activity-toolbar{flex-wrap:wrap}.activity-toolbar>div{width:100%}.activity-toolbar button{flex:1;font-size:11px;padding:10px}.activity-fields{grid-template-columns:1fr 1fr}.activity-editor{padding:20px 15px}.activity-item-actions .secondary-button{font-size:11px}}
</style>
